/**
 * Expo config plugin — a release build is signed with the GeminiSecure release key, and with nothing else (M33 §2).
 *
 * Until M33 every APK shipped on the Android DEBUG key: the template's `release { signingConfig signingConfigs.debug }`,
 * a certificate (CN=Android Debug, SHA-256 fac61745…) that every React Native project in the world shares. An app signed
 * with it can be replaced on a phone by anybody's build. This plugin is what changes that, and it has to be a plugin:
 * `android/` is generated by `expo prebuild` and not committed, so an edit to build.gradle lasts one build.
 *
 * WHAT IT WRITES INTO app/build.gradle:
 *   - a `release` signing config: v1, v2 and v3 signatures, the key named by `alias` (guard | resident);
 *   - the release build type pointed at it, never at `debug` again;
 *   - `gsCheckReleaseKey`, run before anything is signed or packaged, which REFUSES the build when there is no release
 *     key, when the key is an Android debug certificate — known by the CERTIFICATE, whatever the file is called — or
 *     when it is not the one recorded in tools/signing/release-certificates.json;
 *   - `gsSignV1V2V3`, run once the APK is packaged: apksigner signs it again with v1, v2 and v3, so it carries all three
 *     whatever the Android Gradle plugin decides for an app whose minSdk is 24. (`apksigner verify` reports v1 only when
 *     asked to verify as for Android 6, `--min-sdk-version 23`: tools/signing/verify-apk.mjs asks it so.)
 *
 * NOTHING SECRET IS WRITTEN. The keystore and its password are read when Gradle runs, from the environment
 * (GS_KEYSTORE_FILE, GS_KEYSTORE_PASSWORD, GS_KEY_PASSWORD) or from the properties file GS_SIGNING_PROPERTIES names —
 * by default %USERPROFILE%\.geminisecure-signing\signing.properties, outside every repository
 * (tools/signing/make-release-keystore.ps1 made it). No message prints a password.
 */

const { withAppBuildGradle } = require('expo/config-plugins')

const MARK = '// GeminiSecure release signing (tools/expo-plugins/withReleaseSigning.cjs, M33 §2).'

const ALIASES = ['guard', 'resident']

/** The certificate every React Native template's debug.keystore carries. */
const DEBUG_CERTIFICATES = ['fac61745dc0903786fb9ede62a962b399f7348f0bb6f899b8332667591033b9c']

function loader(alias) {
  return [
    MARK,
    '// Nothing secret is in this file: the key and its password are read from the environment or from a properties file',
    '// outside the repository, and no message prints a password.',
    'def gsSigning = {',
    '    def props = new Properties()',
    "    def path = System.getenv('GS_SIGNING_PROPERTIES') ?: (findProperty('GS_SIGNING_PROPERTIES') ?: (System.getProperty('user.home') + '/.geminisecure-signing/signing.properties'))",
    '    def file = new File(path)',
    '    if (file.isFile()) {',
    '        file.withInputStream { props.load(it) }',
    '    }',
    '    def pick = { String env, String key -> System.getenv(env) ?: props.getProperty(key) }',
    '    return [',
    "        where: file.isFile() ? path : ('GS_KEYSTORE_FILE, or ' + path),",
    "        storeFile: pick('GS_KEYSTORE_FILE', 'storeFile'),",
    "        storePassword: pick('GS_KEYSTORE_PASSWORD', 'storePassword'),",
    "        keyPassword: pick('GS_KEY_PASSWORD', 'keyPassword'),",
    `        alias: '${alias}',`,
    '    ]',
    '}()',
    '',
  ].join('\n')
}

const SIGNING_CONFIG = [
  '        release {',
  '            if (gsSigning.storeFile) {',
  '                storeFile file(gsSigning.storeFile)',
  '                storePassword gsSigning.storePassword',
  '                keyAlias gsSigning.alias',
  '                keyPassword gsSigning.keyPassword',
  '            }',
  '            // v1 for the oldest installers; v2 and v3 for every Android since 7, and a key that can be rotated later.',
  '            enableV1Signing true',
  '            enableV2Signing true',
  '            enableV3Signing true',
  '        }',
].join('\n')

const CHECK = [
  '',
  MARK,
  '// A release is signed with the GeminiSecure key and never with a debug one, known by the CERTIFICATE whatever the file',
  '// is called, and it is the key tools/signing/release-certificates.json records. Run before anything is signed.',
  `def gsDebugCertificates = [${DEBUG_CERTIFICATES.map((sha) => `'${sha}'`).join(', ')}]`,
  "tasks.register('gsCheckReleaseKey') {",
  '    doLast {',
  '        def s = gsSigning',
  '        if (!s.storeFile || !s.storePassword) {',
  '            throw new GradleException("No GeminiSecure release key: nothing at " + s.where + " names one. A release is never signed with the debug key (M33 §2).")',
  '        }',
  '        def keystore = java.security.KeyStore.getInstance(new File(s.storeFile), s.storePassword.toCharArray())',
  '        def certificate = keystore.getCertificate(s.alias)',
  '        if (certificate == null) {',
  '            throw new GradleException("The release keystore holds no key called " + s.alias + ".")',
  '        }',
  "        def sha256 = java.security.MessageDigest.getInstance('SHA-256').digest(certificate.encoded).encodeHex().toString()",
  '        def subject = certificate.subjectX500Principal.name',
  "        if (subject.contains('CN=Android Debug') || gsDebugCertificates.contains(sha256)) {",
  '            throw new GradleException("Refused: the release key " + s.alias + " is an Android DEBUG certificate (" + sha256 + ", " + subject + "). A release is signed with the GeminiSecure key (M33 §2).")',
  '        }',
  "        def recorded = new File(rootDir.getAbsoluteFile().getParentFile(), '../../tools/signing/release-certificates.json')",
  '        if (recorded.isFile()) {',
  '            def expected = new groovy.json.JsonSlurper().parse(recorded)[s.alias]',
  '            if (expected && expected != sha256) {',
  '                throw new GradleException("Refused: the release key " + s.alias + " is " + sha256 + ", and tools/signing/release-certificates.json records " + expected + ". This is not the GeminiSecure key.")',
  '            }',
  '        }',
  '        logger.lifecycle("GeminiSecure release key " + s.alias + ": " + subject + ", SHA-256 " + sha256)',
  '    }',
  '}',
  "tasks.matching { it.name in ['validateSigningRelease', 'packageRelease', 'bundleRelease', 'assembleRelease'] }.configureEach {",
  "    dependsOn 'gsCheckReleaseKey'",
  '}',
  '',
  '// …and v1 as well, whatever the Android Gradle plugin decides for a minSdk of 24: the packaged APK is signed again by',
  '// apksigner with all three schemes. The password reaches apksigner through its environment (--ks-pass env:), never',
  '// its command line.',
  "tasks.register('gsSignV1V2V3') {",
  '    doLast {',
  '        def s = gsSigning',
  "        def apk = new File(layout.buildDirectory.get().asFile, 'outputs/apk/release/app-release.apk')",
  '        if (!apk.isFile()) {',
  '            throw new GradleException("No release APK at " + apk + " to sign.")',
  '        }',
  "        def windows = System.getProperty('os.name').toLowerCase().contains('windows')",
  "        def apksigner = new File(android.sdkDirectory, 'build-tools/' + android.buildToolsVersion + '/' + (windows ? 'apksigner.bat' : 'apksigner'))",
  "        def command = [apksigner.absolutePath, 'sign', '--ks', s.storeFile, '--ks-type', 'PKCS12', '--ks-key-alias', s.alias,",
  "            '--ks-pass', 'env:GS_APKSIGNER_SECRET', '--key-pass', 'env:GS_APKSIGNER_SECRET',",
  "            '--v1-signing-enabled', 'true', '--v2-signing-enabled', 'true', '--v3-signing-enabled', 'true', apk.absolutePath]",
  '        def builder = new ProcessBuilder(command).redirectErrorStream(true)',
  "        builder.environment().put('GS_APKSIGNER_SECRET', s.storePassword)",
  '        def process = builder.start()',
  '        def said = process.inputStream.text',
  '        if (process.waitFor() != 0) {',
  '            throw new GradleException("apksigner could not sign " + apk.name + ": " + said)',
  '        }',
  '        logger.lifecycle("GeminiSecure release " + s.alias + ": " + apk.name + " signed v1, v2 and v3 by apksigner")',
  '    }',
  '}',
  "tasks.matching { it.name == 'packageRelease' }.configureEach {",
  "    finalizedBy 'gsSignV1V2V3'",
  '}',
  '',
].join('\n')

/**
 * The template's app/build.gradle, signed for a release with the GeminiSecure key. Idempotent; throws on a template it
 * does not recognise rather than leaving a release signed with the debug key.
 */
function applyReleaseSigning(contents, alias) {
  if (!ALIASES.includes(alias)) {
    throw new Error(`withReleaseSigning: the key is called guard or resident, not ${JSON.stringify(alias)}.`)
  }

  if (contents.includes(MARK)) {
    return contents
  }

  const android = contents.search(/^android \{/m)
  if (android === -1) {
    throw new Error('withReleaseSigning: app/build.gradle has no `android {` block to sign.')
  }

  let out = contents.slice(0, android) + loader(alias) + contents.slice(android)

  const debugConfig = /(signingConfigs \{\n(?:[ \t]*)debug \{[\s\S]*?\n(?:[ \t]*)\}\n)/
  if (!debugConfig.test(out)) {
    throw new Error('withReleaseSigning: app/build.gradle has no `signingConfigs { debug { … } }` to add the release key beside.')
  }
  out = out.replace(debugConfig, (match) => `${match}${SIGNING_CONFIG}\n`)

  const releaseType = /(buildTypes \{[\s\S]*?\n[ \t]*release \{[\s\S]*?)signingConfig signingConfigs\.debug/
  if (!releaseType.test(out)) {
    throw new Error('withReleaseSigning: the release build type is not signed with signingConfigs.debug as the template is; nothing was changed.')
  }
  out = out.replace(releaseType, (_, before) => `${before}signingConfig signingConfigs.release`)

  return out + CHECK
}

module.exports = function withReleaseSigning(config, options = {}) {
  const alias = options.alias
  return withAppBuildGradle(config, (mod) => {
    mod.modResults.contents = applyReleaseSigning(mod.modResults.contents, alias)
    return mod
  })
}

module.exports.applyReleaseSigning = applyReleaseSigning
module.exports.DEBUG_CERTIFICATES = DEBUG_CERTIFICATES
module.exports.MARK = MARK
